<script>
 import {untrack} from 'svelte';
 import {createConversationSession,conversationCitations} from './investigationConversation.js';
 import {fetchQuickGenerateConfig,fetchQuickGenerateModels} from './api.js';
 let {repo,number,headRef,question,locations,top,onClose,onInspect,onFinding}=$props();
 let storageError=$state(''),config=$state(null),configError=$state(''),key=$state(''),model=$state(''),models=$state([]),loadingModels=$state(false),loadId=0,modelRequest;
 const controller=new AbortController();
 const session=createConversationSession({key:untrack(()=>`prview:conversation:v1:${repo}#${number}:${question.id}`),storage:localStorage,repo,headRef,onError:error=>storageError=error});
 let snapshot=$state(session.actor.getSnapshot());const subscription=session.actor.subscribe(value=>snapshot=value);
 $effect(()=>()=>{controller.abort();subscription.unsubscribe();session.dispose();});
 const provider=$derived(config?.keys.find(item=>item.id===key));
 const busy=$derived(snapshot.matches('asking'));
 async function loadModels(selected){const id=++loadId;modelRequest?.abort();const pending=new AbortController();modelRequest=pending;const cancel=()=>pending.abort();controller.signal.addEventListener('abort',cancel,{once:true});key=selected;model='';models=[];loadingModels=true;configError='';try{const values=await fetchQuickGenerateModels(selected,pending.signal);if(id!==loadId)return;models=values;model=values.some(item=>item.id===config.defaultModel)?config.defaultModel:values[0]?.id ?? '';if(!model)configError='This provider listed no usable models.';}catch(error){if(!controller.signal.aborted && id===loadId)configError=error.message;}finally{controller.signal.removeEventListener('abort',cancel);if(id===loadId)loadingModels=false;}}
 async function configure(){configError='';try{config=await fetchQuickGenerateConfig(controller.signal);if(controller.signal.aborted)return;if(config.keys.length)await loadModels(config.defaultKey || config.keys[0].id);}catch(error){if(!controller.signal.aborted)configError=error.message;}}
 void configure();
 function ask(){session.send({type:'ASK',key,provider:provider?.label ?? '',model,locations:locations.map(item=>({...item}))});}
 function finding(turn){onFinding(`AI-assisted investigation — verify against source.\n\nQuestion: ${turn.question}\n\n${turn.answer}`,conversationCitations(turn.answer,turn.sources),question);}
</script>
<aside class="conversation" aria-label="Investigation conversation" style:top={`${top}px`} data-code-overlay onkeydown={event=>{event.stopPropagation();if(event.key==='Escape'){event.preventDefault();onClose();}}}>
 <header><strong>Ask about code</strong><button aria-label="Close investigation conversation" onclick={onClose}>×</button></header>
 <small>{question.title} · Private in this browser</small>
 {#if storageError}<p role="alert">{storageError}</p>{/if}
 {#if !config && !configError}<p role="status">Checking configured providers…</p>{:else if config && !config.keys.length}<p role="status">No AI provider is configured. Add a supported API key through the existing Quick Generate settings, then retry. Your question can still be saved here.</p><a href="#/settings" onclick={onClose}>Open provider settings</a><button onclick={configure}>Retry provider configuration</button>{:else if config}<div class="provider"><select aria-label="Conversation provider" disabled={busy} value={key} onchange={event=>loadModels(event.currentTarget.value)}>{#each config.keys as item}<option value={item.id}>{item.label}</option>{/each}</select><select aria-label="Conversation model" disabled={busy || loadingModels} bind:value={model}>{#each models as item}<option value={item.id}>{item.id}</option>{/each}</select></div>{/if}
 {#if configError}<p role="alert">{configError} <button onclick={configure}>Retry</button></p>{/if}
 <div class="turns">{#each snapshot.context.turns as turn}<article><h3>{turn.question}</h3><small>{turn.provider} · {turn.model} · {new Date(turn.at).toLocaleString()}</small><pre>{turn.answer}</pre><div class="citations">{#each conversationCitations(turn.answer,turn.sources) as source}<button onclick={()=>onInspect(source)} title={source.rev}>{source.file}:{source.line}{source.endLine>source.line?`–${source.endLine}`:''} · {source.rev.slice(0,7)}{source.truncated?' · partial excerpt':''}</button>{/each}</div><button onclick={()=>finding(turn)}>Save as finding</button></article>{/each}{#if busy}<article aria-live="polite"><small>{snapshot.context.partial?'Answering…':'Loading pinned source and asking provider…'}</small><pre>{snapshot.context.partial}</pre></article>{/if}</div>
 <div class="compose"><details><summary>Source context sent on Ask ({Math.min(locations.length,4)} locations)</summary>{#each locations as source}<small>{source.file}:{source.line} · {source.rev.slice(0,7)}</small>{/each}<p>Up to32 lines around each location, your question and the last6 turns go to {provider?.label ?? 'the selected provider'}. Findings and review drafts are excluded. Answers are unverified; only citations inside supplied excerpts become code links.</p></details><textarea aria-label="Private investigation question" maxlength="2000" disabled={busy} placeholder="Ask about the selected code…" value={snapshot.context.draft} oninput={event=>session.send({type:'DRAFT',value:event.currentTarget.value})}></textarea>{#if snapshot.context.error}<p role="status">{snapshot.context.error}</p>{/if}{#if snapshot.context.turns.length>=40}<p>Conversation reached40 turns. Start another investigation to continue.</p>{/if}<div>{#if busy}<button onclick={()=>session.send({type:'CANCEL'})}>Cancel answer</button>{:else}<button disabled={!key || !model || loadingModels || !snapshot.context.draft.trim() || snapshot.context.turns.length>=40} onclick={ask}>Ask {provider?.label ?? 'provider'}</button>{/if}</div></div>
</aside>
<style>
 .conversation{position:fixed;z-index:98;right:8px;bottom:38px;width:min(400px,calc(100vw - 24px));display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--border);border-radius:8px;box-shadow:var(--shadow-dialog);font:12px/1.5 system-ui;overflow:auto;}header{display:flex;justify-content:space-between;padding:8px 10px;border-bottom:1px solid var(--border);}aside>small,aside>p,aside>a{margin:7px 10px;}small{display:block;font-size:10px;color:var(--text-dim);overflow-wrap:anywhere;}button,select,textarea{color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:4px;font:inherit;padding:5px 7px;}button{cursor:pointer;}button:disabled{opacity:.4;cursor:default;}button:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--link);}a{color:var(--link);}p{font-size:11px;}header button{border:0;padding:0 5px;} .provider{display:flex;gap:5px;margin:7px 10px;}.provider select{min-width:0;width:50%;font-size:10px;}.turns{flex:1;min-height:40px;overflow:auto;}article{padding:10px;border-bottom:1px solid var(--border);}h3{font-size:12px;margin:0 0 5px;}pre{font:12px/1.6 system-ui;white-space:pre-wrap;overflow-wrap:anywhere;}.citations{display:flex;flex-direction:column;gap:4px;margin:8px 0;}.citations button{text-align:left;color:var(--link);font:10px monospace;overflow-wrap:anywhere;}.compose{padding:10px;border-top:1px solid var(--border);}summary{cursor:pointer;font-size:10px;color:var(--text-dim);}textarea{width:100%;box-sizing:border-box;min-height:80px;margin:8px 0;resize:vertical;}.compose>div{text-align:right;}
</style>
